it('should NOT normalize case', () => {
	const foo = () => {};
	inst.on('FOO', foo);
	inst.on('Bar', foo);
	inst.on('baz:bat!', foo);

	inst.off('FOO', foo);
	inst.off('Bar', foo);
	inst.off('baz:baT!', foo);

